  <div class="carousel-wrapper">
    <div class="carousel-track">
      <img src="http://localhost:1313/images/20251015_1.jpg" class="carousel-img" loading="lazy" />
      <img src="http://localhost:1313/images/20251015_2.jpg" class="carousel-img" loading="lazy" />
